import{_ as l,o as t,c as i,a2 as r}from"./chunks/framework.BV21bweQ.js";const c=JSON.parse('{"title":"维斯塔黑化支线（平行时间线）","description":"","frontmatter":{},"headers":[],"relativePath":"叙事与伏笔/维斯塔黑化.md","filePath":"叙事与伏笔/维斯塔黑化.md","lastUpdated":1787066340000}'),o={name:"叙事与伏笔/维斯塔黑化.md"};function e(n,a,s,h,u,d){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="维斯塔黑化支线-平行时间线" tabindex="-1">维斯塔黑化支线（平行时间线） <a class="header-anchor" href="#维斯塔黑化支线-平行时间线" aria-label="Permalink to &quot;维斯塔黑化支线（平行时间线）&quot;">​</a></h1><p>本支线为平行时间线节点：源自间章神机黑化的分支。若玩家在间章时期的选择不足、未能做到某些事情，神机会彻底黑化、彻底失控，产生与正传正好相反的世界线；此线中维斯塔彻底黑化，成为&quot;赤色暴君&quot;。</p><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to &quot;来源&quot;">​</a></h2><p>维斯塔黑化的平行时间线，来源于<strong>神机黑化的部分</strong>（间章部分）。</p><p><strong>关键认知</strong>：</p><ul><li>在间章很大一部分时间线中，<strong>神机的发展会受主角影响</strong></li><li>神机的黑化在官方时间线中是&quot;正常的，可控的&quot;</li><li>但在玩家选择的其余支线中，情况会不同</li></ul><h2 id="触发条件" tabindex="-1">触发条件 <a class="header-anchor" href="#触发条件" aria-label="Permalink to &quot;触发条件&quot;">​</a></h2><p>如果玩家在当时的选择不够、没有做到某些事情：</p><ul><li>神机会<strong>彻底黑化、彻底失控</strong></li><li>产生与正传<strong>正好相反</strong>的世界线</li></ul><h2 id="黑化维斯塔的形象" tabindex="-1">黑化维斯塔的形象 <a class="header-anchor" href="#黑化维斯塔的形象" aria-label="Permalink to &quot;黑化维斯塔的形象&quot;">​</a></h2><p>在这个相反的世界线中：</p><ul><li><strong>维斯塔彻底黑化</strong>，变成&quot;赤色暴君&quot;</li><li>维斯塔黑化后同样追求进取，但<strong>更加务实，也更加残暴</strong></li><li>不像神机黑化后会谨慎，维斯塔更加极端、更加不顾代价</li><li><strong>但本质上是主线神机的&quot;同位体&quot;，定位都为&quot;守护者&quot;角色</strong></li></ul><h2 id="力量对比" tabindex="-1">力量对比 <a class="header-anchor" href="#力量对比" aria-label="Permalink to &quot;力量对比&quot;">​</a></h2><ul><li>执念的能量<strong>比神机的不断进步更大</strong></li><li>黑化后的维斯塔<strong>非常非常强大</strong></li><li>积极入世，统治着十分庞大的势力</li></ul><h2 id="统治方式" tabindex="-1">统治方式 <a class="header-anchor" href="#统治方式" aria-label="Permalink to &quot;统治方式&quot;">​</a></h2><p>黑化维斯塔的统治：</p><ul><li><strong>民众狂热、极端、忠诚</strong></li><li><strong>不择手段</strong></li><li>不再是&quot;正义的&quot;</li><li>他<strong>控制了三神权</strong>： <ol><li>他自己的变化神权</li><li>剥离控制了毁灭神的神权</li><li>强行继承了创造神的神权（并非神机的神权，此处为下位创造，而非神机的上位创造）</li></ol></li></ul><h2 id="目的" tabindex="-1">目的 <a class="header-anchor" href="#目的" aria-label="Permalink to &quot;目的&quot;">​</a></h2><p>黑化维斯塔的核心目的是：<strong>把神机救回来</strong></p><h2 id="实现方式" tabindex="-1">实现方式 <a class="header-anchor" href="#实现方式" aria-label="Permalink to &quot;实现方式&quot;">​</a></h2><ol><li>从支线并入主线</li><li>来到主线世界</li><li><strong>为什么要并入主线</strong>：支线的剧情已经结束了，叙事的力量不复存在</li><li>他需要借助<strong>叙事的力量</strong>——因为叙事才有奇迹</li><li>让自己出现在主线中，让故事继续下去，让自己的目光被叙事注意到</li><li>最终目的是<strong>复活神机</strong></li></ol><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../中层/历史/间章历史" class="layer-link" data-layer="中层">间章历史</a></li><li><a href="./../中层/人物/神机" class="layer-link" data-layer="中层">神机</a></li><li><a href="./../中层/人物/维斯塔" class="layer-link" data-layer="中层">维斯塔</a></li><li><a href="./../底层/规则/叙事与玩家">叙事与玩家</a></li><li><a href="./伏笔洋葱层分类">伏笔洋葱层分类</a></li></ul>',24)])])}const q=l(o,[["render",e]]);export{c as __pageData,q as default};
